import { useAtom } from "@effect/atom-react"
import { Atom } from "effect/reactivity"

type Lane = {
  readonly id: string
  readonly title: string
}

type BoardLaneFilterProps = {
  readonly boardId: string
  readonly lanes: ReadonlyArray<Lane>
}

export function BoardLaneFilter({ boardId, lanes }: BoardLaneFilterProps) {
  const selectedLaneAtom = useMemo(() => Atom.make("all"), [boardId])
  const [selectedLane, setSelectedLane] = useAtom(selectedLaneAtom)

  return (
    <nav aria-label="Filter board by lane">
      <button
        aria-pressed={selectedLane === "all"}
        onClick={() => setSelectedLane("all")}
      >
        All lanes
      </button>
      {lanes.map((lane) => (
        <button
          key={lane.id}
          aria-pressed={selectedLane === lane.id}
          onClick={() => setSelectedLane(lane.id)}
        >
          {lane.title}
        </button>
      ))}
